mapper.insert:
INSERT INTO TB_QUAL_DIAG_HISTORY (
    DIAG_ID, DM_ID, DIAG_TYPE, STATUS,
    TARGET_OBJ_LIST, SAMPLE_RATE, INCREMENTAL_YN, LAST_DIAG_DT,
    EXEC_USER_ID
) VALUES (
    #{diagId}, #{dmId}, #{diagType}, COALESCE(#{status}, 'READY'),
    #{targetObjList}, COALESCE(#{sampleRate}, 100),
    COALESCE(#{incrementalYn}, 'N'), #{lastDiagDt},
    #{execUserId}
)

mapper.select:
SELECT MAX(END_DT)
  FROM TB_QUAL_DIAG_HISTORY
 WHERE DM_ID     = #{dmId}
   AND DIAG_TYPE = #{diagType}
   AND STATUS    = 'DONE'

SELECT h.DIAG_ID AS "diagId", h.DM_ID AS "dmId", dm.DM_NM AS "dataModelNm", h.DIAG_TYPE AS "diagType", h.DIAG_DT AS "diagDt", h.END_DT AS "endDt", h.STATUS AS "status", COALESCE(h.TOTAL_RULES, 0) AS "totalRules", COALESCE(h.TOTAL_COLS, 0) AS "totalCols", COALESCE(h.TOTAL_VIOLATIONS, 0) AS "totalViolations", COALESCE(h.PROGRESS_DONE, 0) AS "progressDone", COALESCE(h.PROGRESS_TOTAL, 0) AS "progressTotal", COALESCE(h.EXEC_USER_ID, '') AS "execUserId" FROM TB_QUAL_DIAG_HISTORY h LEFT JOIN TB_DATA_MODEL dm ON dm.DM_ID = h.DM_ID
AND h.DM_ID = #{dmId} AND h.DIAG_TYPE = #{diagType}
ORDER BY h.DIAG_DT DESC LIMIT 50

mapper.insert:
INSERT INTO TB_QUAL_RULE_RESULT (
    DIAG_ID, RULE_ID, OBJ_NM, ATTR_NM,
    TOTAL_CNT, VIOLATION_CNT, VIOLATION_RATE, SAMPLE_CNT, ERROR_MSG
) VALUES (
    #{diagId}, #{ruleId},
    COALESCE(#{objNm}, ''), COALESCE(#{attrNm}, ''),
    #{totalCnt}, #{violationCnt}, #{violationRate},
    COALESCE(#{sampleCnt}, 0), #{errorMsg}
)

INSERT INTO TB_QUAL_VIOLATION_SAMPLE (
    DIAG_ID, RULE_ID, OBJ_NM, ATTR_NM, SEQ,
    PK_VALUES, VIOLATING_VAL
) VALUES (
    #{diagId}, #{ruleId},
    COALESCE(#{objNm}, ''), COALESCE(#{attrNm}, ''),
    #{seq}, #{pkValues}, #{violatingVal}
)
